import {foodPages,foodCases} from './food-links-content.mjs';
import {foodView,startFood,resumeFood,setFoodPage,setFoodView,chooseFoodNeighbor,chooseFoodMeaning,addFoodSupport,checkFood,foodCheckMatches} from './food-links-core.mjs';
import {foodLinkDiagram} from './food-links-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const card=(source,id)=>source.cards.find(c=>c.id===id);
const cardLabel=(source,id)=>id===null?'No card chosen':id==='unsure'?'Not sure yet':card(source,id)?.label||id;
const meaningLabel=(source,id)=>source.meanings.find(m=>m.id===id)?.label||'No meaning chosen';
const matchLabel=value=>value===null?'not assessed':value?'fits':'does not fit';
const legend=source=>`<p class="food-legend">${esc(source.legend)}</p>`;
function proposed(source,input){if(!input.neighbor||input.neighbor==='unsure')return `<section class="food-proposed"><h3>Our proposed feeding link</h3><p>No pair chosen yet. Choose a food or eater card to propose a link; no answer has been supplied.</p></section>`;const from=source.role==='eater'?input.neighbor:source.reference,to=source.role==='eater'?source.reference:input.neighbor;return `<section class="food-proposed" data-food-from="${from}" data-food-to="${to}"><h3>Our proposed feeding link</h3><div class="food-forward-pair"><div>${foodLinkDiagram(card(source,from))}<strong>${esc(cardLabel(source,from))}</strong><span>Proposed food</span></div><div class="food-link"><span class="food-link-direction">Food to eater</span><span class="food-arrow" aria-hidden="true">→</span></div><div>${foodLinkDiagram(card(source,to))}<strong>${esc(cardLabel(source,to))}</strong><span>Proposed eater</span></div></div><p><strong>Proposed direction:</strong> ${esc(cardLabel(source,from))} (food) → ${esc(cardLabel(source,to))} (eater).</p>${from==='bean'&&to==='aphid'?'<p class="tiny">For the plant card, sap is the food material; the whole plant is not swallowed.</p>':''}<p class="tiny">This is our proposed pair, not a confirmed feeding relationship.</p></section>`;}
function fullSource(source){return `<details class="food-frozen-source"><summary>Original pictures, names and facts kept with this task</summary>${legend(source)}<p>${esc(source.overview)}</p><div class="food-source-cards">${source.cards.map(c=>`<section><h4>${esc(c.label)}</h4><p class="tiny"><i>${esc(c.scientificName)}</i></p>${foodLinkDiagram(c)}<p>${esc(c.text)}</p>${hearButton(c.text,`Hear about ${c.label}`)}</section>`).join('')}</div><ul>${source.links.map(link=>`<li><strong>${esc(cardLabel(source,link.from))} → ${esc(cardLabel(source,link.to))}:</strong> ${esc(link.text)}</li>`).join('')}</ul><p class="tiny">A supplied possible feeding path, not a complete diet list, a real garden observation or a relative-size comparison.</p></details>`;}
function inspect(r){const selected=card(r.source,r.view);return `<h2 id="food-prompt" tabindex="-1">Who can get food from whom?</h2><div class="food-inspect-layout"><section>${foodLinkDiagram(selected)}</section><section><h3>${esc(selected.label)}</h3><p>${esc(selected.text)}</p>${hearButton(selected.text,'Hear this food card')}<div class="food-view-choices" role="group" aria-label="Choose an inspection picture">${r.source.cards.map(c=>button(`data-food-view="${c.id}" aria-pressed="${r.view===c.id}"`,c.label,r.view===c.id)).join('')}</div>${button('data-food-page="connect"','Choose a feeding link',true)}</section></div><p class="tiny">These named teaching pictures supply facts. They are not a species-identification test, and their sizes are chosen for clarity.</p>`;}
function connect(r){const reference=card(r.source,r.source.reference);return `<h2 id="food-prompt" tabindex="-1">${esc(r.source.question)}</h2><div class="food-connect-layout"><section class="food-reference"><h3>Reference ${r.source.role==='eater'?'eater':'food'}: ${esc(reference.label)}</h3>${foodLinkDiagram(reference)}${hearButton(r.source.question+' '+reference.text,'Hear this question and reference')}<details id="food-reference-text" data-round="${r.id}"><summary>Read or hear the reference card</summary><p>${esc(reference.text)}</p>${hearButton(reference.text,'Hear the reference card')}</details></section><section class="food-neighbor"><h3>Choose a card for this link</h3><div class="food-picture-choices" role="group" aria-label="Choose the food or eater card">${r.source.options.map(id=>{const c=card(r.source,id);return `<button type="button" class="food-picture-choice${r.neighbor===id?' selected':''}" data-food-neighbor="${id}" aria-label="${esc(c.label)}" aria-pressed="${r.neighbor===id}">${foodLinkDiagram(c,true)}<strong>${esc(c.label)}</strong><span class="food-tick" aria-hidden="true">${r.neighbor===id?'✓':''}</span></button>`;}).join('')}</div>${button(`data-food-neighbor="unsure" aria-pressed="${r.neighbor==='unsure'}"`,'Not sure yet',r.neighbor==='unsure')}</section></div>${button('data-food-page="meaning"','Next: read our food arrow',true)}`;}
function meaning(r){const options=[...r.source.meaningOptions,'unsure'];return `<h2 id="food-prompt" tabindex="-1">Read our proposed food arrow</h2><p class="food-chart-question"><strong>Current question:</strong> ${esc(r.source.question)}</p>${hearButton(r.source.question+' What would the correct food arrow mean? '+options.map(id=>meaningLabel(r.source,id)).join(' '),'Hear this arrow question')}${proposed(r.source,{neighbor:r.neighbor})}<fieldset class="food-meaning"><legend>What would the correct food arrow mean?</legend><div class="food-meaning-choices" role="group" aria-label="Meaning of the correct food arrow">${options.map(id=>button(`data-food-meaning="${id}" aria-pressed="${r.meaning===id}"`,meaningLabel(r.source,id),r.meaning===id)).join('')}</div></fieldset>${button('data-food-check','Check / keep this trail',true)}<p class="tiny">Blank and uncertain choices can be kept. Latest 8 trails stay in this visit; keeping a ninth removes the oldest.</p>${button('data-food-page="connect"','Change our card choice')}`;}
function record(r,c,index){return `<section class="food-record" tabindex="-1"><h3>${index===r.checks.length-1&&foodCheckMatches(r,c)?'Latest kept trail for these choices':'Earlier recorded trail'}</h3>${legend(c.source)}<p><strong>Recorded question:</strong> ${esc(c.source.question)}</p><p><strong>Chosen neighbor:</strong> ${esc(cardLabel(c.source,c.input.neighbor))}.<br><strong>Chosen meaning:</strong> ${esc(meaningLabel(c.source,c.input.meaning))}.</p><p><strong>Recorded neighbor outcome:</strong> ${matchLabel(c.neighborMatch)}.<br><strong>Recorded meaning outcome:</strong> ${matchLabel(c.meaningMatch)}.</p><p class="food-feedback">${esc(c.feedback)}</p><details><summary>Proposed pair kept with this check</summary>${proposed(c.source,c.input)}</details><p class="tiny">Support requested by this check: ${esc(c.input.support.join(', ')||'none recorded')}. Supplied facts and a no-extra-help record do not establish independent reading or scientific discovery.</p>${fullSource(c.source)}</section>`;}
function kept(r){return `<h2 id="food-prompt" tabindex="-1">Our revisable feeding trail</h2>${r.checks.length?record(r,r.checks.at(-1),r.checks.length-1):'<p>No trail has been kept yet. Your card and meaning choices stay available.</p>'}${button('data-food-page="connect"','Change our trail',true)} ${button('data-food-page="inspect"','Inspect the food cards')}${r.checks.length>1?`<details><summary>Earlier kept trails (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>record(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="food-catalog"><h2>Choose a food-link question</h2><p>Four questions share one named feeding path. All questions are open.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="food-start-form"><label for="food-case">Food-link question</label><select name="case" id="food-case">${foodCases.map(s=>`<option value="${s.id}"${v.current?.source.id===s.id?' selected':''}>${esc(s.question)}</option>`).join('')}</select><button class="secondary" type="submit">Start this question</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our feeding-path visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-food-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work stays unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function foodLinksPage(state){const v=foodView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#living"><span aria-hidden="true">←</span> Living Garden</a><h1>Food to eater</h1><p>The wildlife corner needs a food-arrow label. Connect the supplied food and eater cards.</p></header>`;if(v.status==='unavailable')return `<div class="food-page">${heading}<section class="food-sheet"><h2>Earlier work is safe</h2><p>This saved feeding-path work uses a format we cannot continue here. It stays unchanged; the garden remains open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.foodLinks,null,2))}</pre></details></section></div>`;return `<div class="food-page">${heading}<section class="food-sheet">${r?`<nav class="food-tabs" aria-label="Food Links pages">${foodPages.map(p=>button(`data-food-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({inspect:'Inspect',connect:'Link',meaning:'Meaning',kept:'Kept trail'})[p],v.page===p)).join('')}</nav><p class="food-task-title">A supplied possible feeding path${r.familiar?' · Familiar path; this question may differ':''}</p>${legend(r.source)}`:''}<p id="food-status" role="status" tabindex="-1" class="food-status"></p>${r?v.page==='connect'?connect(r):v.page==='meaning'?meaning(r):v.page==='kept'?kept(r):inspect(r):`<h2 id="food-prompt" tabindex="-1">Open a feeding-path picture story</h2><p>Arrows in this example point from food to eater. These are different organisms, not stages of one creature.</p>${catalog(v)}`}${r?`<details id="food-facts" data-round="${r.id}"><summary>Our named feeding path and facts</summary><p>${esc(r.source.overview)}</p>${fullSource(r.source)}${hearButton(r.source.overview,'Hear the overview')}<a class="food-contrast-link" href="#living/stages">Compare with the Life Stages arrow legend</a></details><details id="food-help" data-round="${r.id}"><summary>Help us read the food arrow</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear this help')}${button('data-food-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another food-link question</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function foodLinksNotes(state){const v=foodView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Food Links · earlier format</summary><pre>${esc(JSON.stringify(state.foodLinks,null,2))}</pre></details>`;return `<details class="panel food-page"><summary>Living Garden Food Links (${v.rounds.length} visits)</summary><p>Original named schematics and supplied facts about one possible feeding path. Neighbor and arrow-meaning outcomes remain separate. Familiarity records the shared path across questions, not mastery. Picture views do not establish inspection or understanding. The existing host connection panel may display/register incoming numerical facts on Living Garden routes. No independent reading, species identification, complete-diet explanation or learning gain is inferred.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3>${legend(r.source)}<p>Familiar path as recorded: ${r.familiar?'yes':'no'}. Support: ${esc(r.support.join(', ')||'none recorded')}. Current draft: ${esc(cardLabel(r.source,r.neighbor))}; ${esc(meaningLabel(r.source,r.meaning))}.</p>${fullSource(r.source)}${r.checks.map((c,i)=>record(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindFoodLinks(state,{save,render,focus}){
 const boundId=foodView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&foodView(state).current?.id===boundId;
 const show=(message='',target='#food-prompt')=>{const id=foodView(state).current?.id,open=[...document.querySelectorAll('.food-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(foodView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#food-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 document.querySelector('#food-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||foodView(state).current?.id!==boundId)return;const r=startFood(state,new FormData(form).get('case'));show(r?'A feeding-path visit is ready. Earlier trails stay in their visits.':'A new visit cannot be created because its saved visit numbers have reached the supported limit. Earlier visits remain available.',r?'#food-prompt':'#food-status');});
 document.querySelectorAll('[data-food-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||foodView(state).current?.id!==boundId)return;const ok=resumeFood(state,Number(b.dataset.foodResume));show(ok?'Earlier path visit opened with its own facts and records.':'That path visit could not be opened.');}));
 bind('[data-food-page]',b=>{setFoodPage(state,b.dataset.foodPage);show();});
 bind('[data-food-view]',b=>{setFoodView(state,b.dataset.foodView);show('Inspection picture changed; answer choices are unchanged.',`[data-food-view="${b.dataset.foodView}"]`);});
 bind('[data-food-neighbor]',b=>{chooseFoodNeighbor(state,b.dataset.foodNeighbor);show('Proposed food or eater changed. The meaning choice stays available.',`[data-food-neighbor="${b.dataset.foodNeighbor}"]`);});
 bind('[data-food-meaning]',b=>{chooseFoodMeaning(state,b.dataset.foodMeaning);show('Meaning choice updated. Earlier records stay unchanged.',`[data-food-meaning="${b.dataset.foodMeaning}"]`);});
 bind('[data-food-check]',()=>{const c=checkFood(state);if(c)setFoodPage(state,'kept');show(c?'This trail is kept with separate neighbor and meaning outcomes.':'This trail could not be kept.',c?'.food-record':'#food-status');});
 bind('[data-food-together]',()=>{addFoodSupport(state,'together');show('Thinking together recorded as support.','[data-food-together]');});
 const help=document.querySelector('#food-help');help?.addEventListener('toggle',()=>{if(help.open&&sameVisit(help)&&Number(help.dataset.round)===boundId){addFoodSupport(state,'help');save();}});
 document.querySelectorAll('.food-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b)){addFoodSupport(state,'audio');save();}}));
}
